from typing import Annotated

from vss_agents.data_models import ParserMixin

from pydantic import BaseModel
from pydantic import Field


class VideoEvent(BaseModel, ParserMixin):
    """Video event"""

    start_timestamp: Annotated[
        float,
        Field(
            ...,
            description="The start time of the video event, in pts(presentation time stamp), seconds",
        ),  # BeforeValidator(remove_timezone),
    ]
    end_timestamp: Annotated[
        float,
        Field(
            ...,
            description="The end time of the video event, in pts(presentation time stamp), seconds",
        ),  # BeforeValidator(remove_timezone),
    ]
    event_description: str = Field(
        ...,
        description="The description of the video event",
    )

    def __str__(self):
        return f"**{self.start_timestamp}-{self.end_timestamp}** {self.event_description}"


class VideoEventList(BaseModel, ParserMixin):
    """List of video events"""

    events: list[VideoEvent] | None = Field(
        None,
        description="The list of video events",
    )
